CREATE FUNCTION public.salvar_parceiro_ct(dados jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE pid uuid; BEGIN IF NOT private.has_role(auth.uid(),'adm') THEN RAISE EXCEPTION 'Acesso restrito'; END IF; pid := (dados->>'id')::uuid; IF length(trim(dados->>'nome'))=0 THEN RAISE EXCEPTION 'Nome obrigatório'; END IF; INSERT INTO public.parceiros_ct(id,nome,logo_url,instagram,ordem,ativo) VALUES(pid,dados->>'nome',dados->>'logo_url',dados->>'instagram',(dados->>'ordem')::integer,(dados->>'ativo')::boolean) ON CONFLICT(id) DO UPDATE SET nome=excluded.nome,logo_url=excluded.logo_url,instagram=excluded.instagram,ordem=excluded.ordem,ativo=excluded.ativo; INSERT INTO public.parceiros_ct_beneficios(id,categoria,descricao,desconto,beneficio,cupom,telefone,condicoes,imagem_url) VALUES(pid,dados->>'categoria',dados->>'descricao',dados->>'desconto',dados->>'beneficio',dados->>'cupom',dados->>'telefone',dados->>'condicoes',dados->>'imagem_url') ON CONFLICT(id) DO UPDATE SET categoria=excluded.categoria,descricao=excluded.descricao,desconto=excluded.desconto,beneficio=excluded.beneficio,cupom=excluded.cupom,telefone=excluded.telefone,condicoes=excluded.condicoes,imagem_url=excluded.imagem_url; RETURN pid; END $$;
REVOKE ALL ON FUNCTION public.salvar_parceiro_ct(jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.salvar_parceiro_ct(jsonb) TO authenticated, service_role;